func (r *ResourceF5XCNetworkPolicy) Delete(ctx context.Context, request resource.DeleteRequest, response *resource.DeleteResponse) {
	var data ResourceF5XCNetworkPolicyModel

	// Read Terraform prior state data into the model
	response.Diagnostics.Append(request.State.Get(ctx, &data)...)
	if response.Diagnostics.HasError() {
		return
	}

	duration, err := time.ParseDuration("10m0s")
	if err != nil {
		response.Diagnostics.AddError(
			"Invalid Duration Format",
			fmt.Sprintf("Could not parse 'timeout' value %q: %s. "+
				"Please use a valid Go duration string like '10m', '1h30m' or '30s'.",
				"10m0s", err.Error()),
		)
		return
	}

	deleteTimeout, diags := data.Timeouts.Delete(ctx, duration)
	response.Diagnostics.Append(diags...)
	if response.Diagnostics.HasError() {
		return
	}

	ctx, cancel := context.WithTimeout(ctx, deleteTimeout)
	defer cancel()
	// Pre-Delete Hook: hook.NetworkPolicyPreDeleteHook
	if hookErr := hook.NetworkPolicyPreDeleteHook(ctx, r.client, data.Namespace.ValueString(), data.Name.ValueString()); hookErr != nil {
		response.Diagnostics.AddError(
			"Pre-Delete Hook Error",
			fmt.Sprintf("Pre-delete hook failed for %s: %s", "network_policy", hookErr),
		)
		return
	}

	// Standard Delete Logic
	opts := []vesapi.CallOpt{}
	opts = append(opts, vesapi.WithFailIfReferred())
	deleteFn := func() error {
		return r.client.DeleteObject(ctx, ves_io_schema_network_policy.ObjectType, data.Namespace.ValueString(), data.Name.ValueString(), opts...)
	}

	err = deleteFn()
	if err != nil && strings.Contains(err.Error(), "is still being referred by") {
		// The object is still referenced by a parent object (e.g. the user is deleting it
		// and re-pointing the parent to another object in the same apply). Reactively
		// detach it from any referring parents Terraform manages, then retry.
		tflog.Info(ctx, fmt.Sprintf("[hook] network_policy delete hit 409, attempting reactive unbind: %s", err))
		if unbindErr := hook.NetworkPolicyUnbindReferencingObjects(ctx, r.client, data.Namespace.ValueString(), data.Name.ValueString(), err.Error()); unbindErr != nil {
			tflog.Warn(ctx, fmt.Sprintf("[hook] network_policy reactive unbind failed: %s", unbindErr))
		}
		// Retry immediately: the unbind above (when it applies) removes the reference
		// that caused the conflict, so there is nothing to gain from sleeping first.
		err = deleteFn()
	}
	if err != nil {
		err = utils.DeleteWithTransientRetry(ctx, "network_policy", deleteFn)
	}

	if err != nil {
		if strings.Contains(err.Error(), "status code 404") || strings.Contains(err.Error(), "NotFound") {
			// Object already gone, Terraform take it easy
			return
		}

		response.Diagnostics.AddError(
			"Client Error", utils.SanitizeAPIError(ctx, "delete", "network_policy", err),
		)
		return
	}

}
func (r *ResourceF5XCNetworkPolicy) ImportState(ctx context.Context, req resource.ImportStateRequest, response *resource.ImportStateResponse) {
	// Import ID format: namespace/name
	parts := strings.Split(req.ID, "/")
	if len(parts) != 2 {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/name, got: %s", req.ID),
		)
		return
	}
	if parts[0] == "" {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/name, got: %s (namespace is empty)", req.ID),
		)
		return
	}
	response.Diagnostics.Append(response.State.SetAttribute(ctx, path.Root("namespace"), parts[0])...)
	if parts[1] == "" {
		response.Diagnostics.AddError(
			"Invalid Import ID",
			fmt.Sprintf("Expected import ID format: namespace/name, got: %s (name is empty)", req.ID),
		)
		return
	}
	response.Diagnostics.Append(response.State.SetAttribute(ctx, path.Root("name"), parts[1])...)
}
